import React, { useState } from 'react';
import './HostGame.css';

const HostGame = ({ onBack }) => {
    // view state'i: 'menu', 'create', veya 'load' olabilir
    const [view, setView] = useState('menu');

    // Yeni Oyun Formu State'leri
    const [campaignName, setCampaignName] = useState('');
    const [joinCode, setJoinCode] = useState('');
    const [campaignDesc, setCampaignDesc] = useState('');

    // Mevcut Oyunlar (Mock Data - İleride veritabanından gelecek)
    const mockCampaigns = [
        { id: 1, name: "Kayıp Madenler", players: 4, lastPlayed: "2 gün önce" },
        { id: 2, name: "Strahd'ın Laneti", players: 6, lastPlayed: "1 hafta önce" }
    ];

    return (
        <div className="sheet-bg">
            <div className="sheet-container host-container fade-in">

                {/* --- ANA MENÜ SEÇİMİ --- */}
                {view === 'menu' && (
                    <div className="host-menu-view">
                        <div className="host-header">
                            <h1 className="host-main-title">Zindan Ustası Masası</h1>
                            <p className="host-subtitle">Kaderlerin yazılacağı evreni seç veya yenisini yarat.</p>
                        </div>

                        <div className="host-cards-container">
                            {/* Yeni Oyun Kartı */}
                            <div className="host-action-card" onClick={() => setView('create')}>
                                <div className="card-icon">⚔️</div>
                                <h2>Yeni Oyun Kur</h2>
                                <p>Sıfırdan bir hikaye başlat, oyuncuların için özel bir davet kodu oluştur.</p>
                            </div>

                            {/* Mevcut Oyun Kartı */}
                            <div className="host-action-card" onClick={() => setView('load')}>
                                <div className="card-icon">📜</div>
                                <h2>Mevcut Oyunu Aç</h2>
                                <p>Yarım kalan maceraya geri dön. Kayıtlı senaryolarını ve oyuncularını yönet.</p>
                            </div>
                        </div>

                        <button className="back-to-main-btn" onClick={onBack}>← ANA MENÜYE DÖN</button>
                    </div>
                )}

                {/* --- YENİ OYUN KURMA EKRANI --- */}
                {view === 'create' && (
                    <div className="host-form-view fade-in">
                        <h2 className="view-title">Yeni Macera Başlat</h2>

                        <div className="host-input-group">
                            <label>Kampanya (Oyun) Adı</label>
                            <input 
                                type="text" 
                                placeholder="Örn: Ejderhanın İni" 
                                value={campaignName} 
                                onChange={(e) => setCampaignName(e.target.value)} 
                            />
                        </div>

                        <div className="host-input-group">
                            <label>Oyuncu Katılım Kodu (Join Code)</label>
                            <input 
                                type="text" 
                                placeholder="Örn: EJDER2026 (Oyuncular bu kodla katılacak)" 
                                value={joinCode} 
                                onChange={(e) => setJoinCode(e.target.value)} 
                            />
                        </div>

                        <div className="host-input-group">
                            <label>Kısa Açıklama / Tema</label>
                            <textarea 
                                placeholder="Karanlık bir fantezi dünyası, bol tuzaklı zindanlar..." 
                                value={campaignDesc} 
                                onChange={(e) => setCampaignDesc(e.target.value)} 
                            />
                        </div>

                        <div className="host-form-actions">
                            <button className="cancel-btn" onClick={() => setView('menu')}>İPTAL</button>
                            <button className="save-btn launch-btn" onClick={() => console.log("Oyun Kuruluyor...", {campaignName, joinCode, campaignDesc})}>
                                MASAYI AÇ (LAUNCH)
                            </button>
                        </div>
                    </div>
                )}

                {/* --- MEVCUT OYUNU YÜKLEME EKRANI --- */}
                {view === 'load' && (
                    <div className="host-list-view fade-in">
                        <h2 className="view-title">Kayıtlı Kampanyalar</h2>

                        <div className="campaign-list">
                            {mockCampaigns.map(camp => (
                                <div className="campaign-list-item" key={camp.id}>
                                    <div className="campaign-info">
                                        <h3>{camp.name}</h3>
                                        <span>Oyuncu Sayısı: {camp.players} | Son Oynanma: {camp.lastPlayed}</span>
                                    </div>
                                    <button className="resume-btn" onClick={() => console.log(`${camp.name} başlatılıyor...`)}>
                                        DEVAM ET
                                    </button>
                                </div>
                            ))}
                        </div>

                        <div className="host-form-actions">
                            <button className="cancel-btn" onClick={() => setView('//Users/emirhan/Desktop/dndweb/src/Components/MainMenu/MainMenu.jsx')}>GERİ DÖN</button>
                        </div>
                    </div>
                )}

            </div>
        </div>
    );
};

export default HostGame;
